export const ProfileSvg = ({ focused, style }) => {
  const color = focused ? "#4B4B4B" : "#808080";
  const updatedXml = profileIcon.replace(/fill="#[0-9A-Fa-f]{6}"/g, `fill="${color}"`);
  return <SvgXml xml={updatedXml} width="100%" height="100%" style={style} />;
};

